namespace CoastalFactory.Editor {
public static class ScreeningTreesAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/ScreeningTrees";
 static readonly List<GameObject> pieces=new List<GameObject>();
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;var parent=Path.GetDirectoryName(p).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(p));}
 static Material Mat(string name,Color color){var existing=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(existing){existing.color=color;return existing;}var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.08f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static void Box(Transform parent,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());pieces.Add(g);}
 static Mesh Bake(Transform root,Material[] materials){var temps=new List<Mesh>();var final=new CombineInstance[materials.Length];for(int i=0;i<materials.Length;i++){var list=new List<CombineInstance>();foreach(var g in pieces)if(g.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*g.transform.localToWorldMatrix});var part=new Mesh();part.CombineMeshes(list.ToArray(),true,true);temps.Add(part);final[i]=new CombineInstance{mesh=part,transform=Matrix4x4.identity};}var mesh=new Mesh{name="ScreeningTrees"};mesh.CombineMeshes(final,false,true);mesh.RecalculateBounds();foreach(var m in temps)Object.DestroyImmediate(m);return mesh;}
 static void Beam(Transform root,string name,Vector3 a,Vector3 b,float width,Material material){Box(root,name,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),material);pieces[pieces.Count-1].transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static Mesh FoliageMesh(){var v=new List<Vector3>();var t=new List<int>();var uv=new List<Vector2>();int sides=9;float[] ys={0,.18f,.45f,.72f,1};float[] rr={.30f,.72f,1,.70f,.04f};for(int j=0;j<5;j++)for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides;v.Add(new Vector3(Mathf.Sin(a)*rr[j],ys[j],Mathf.Cos(a)*rr[j]));uv.Add(new Vector2(i/(float)sides,ys[j]));}for(int j=0;j<4;j++)for(int i=0;i<sides;i++){int n=j*(sides+1)+i;t.AddRange(new[]{n,n+1,n+sides+1,n+1,n+sides+2,n+sides+1});}var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();return m;}
 [MenuItem("Anseong/Art/Build Screening Trees")]
 public static void Build(){Folder(Root);var leaf=Mat("FoliageMid",new Color(.18f,.27f,.12f));var shade=Mat("FoliageDark",new Color(.10f,.18f,.075f));var tips=Mat("FoliageTips",new Color(.28f,.36f,.17f));var bark=Mat("Trunk",new Color(.25f,.19f,.12f));var mats=new[]{leaf,shade,tips,bark};int total=0;var clump=FoliageMesh();
 for(int variant=0;variant<3;variant++){pieces.Clear();var rand=new System.Random(165+variant);var root=new GameObject("ScreeningTree_"+(char)('A'+variant));var r=root.transform;float height=2.4f+variant*.2f;Box(r,"Trunk",new Vector3(0,.40f,0),new Vector3(.095f,.8f,.095f),bark);
  void Add(Vector3 p,Vector3 scale,int index){var g=new GameObject("DenseEvergreenSpray",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(r,false);g.transform.localPosition=p;g.transform.localScale=scale;g.transform.localRotation=Quaternion.Euler((float)rand.NextDouble()*12-6,(float)rand.NextDouble()*360,(float)rand.NextDouble()*12-6);g.GetComponent<MeshFilter>().sharedMesh=clump;g.GetComponent<Renderer>().sharedMaterial=mats[index];pieces.Add(g);}
  // Dense foliage starts near the ground, tapering to a rounded upright crown.
  for(int level=0;level<7;level++){float y=.16f+level*(height-.62f)/7;float w=Mathf.Lerp(.46f,.19f,level/6f);int count=level<5?7:5;for(int i=0;i<count;i++){float a=i*Mathf.PI*2/count+level*.61f;float radius=w*.48f;Add(new Vector3(Mathf.Sin(a)*radius,y,Mathf.Cos(a)*radius),new Vector3(w*.68f,.64f+level*.018f,w*.68f),level%3==0?1:(i+level+variant)%3);}}
  Add(new Vector3(0,height-.60f,0),new Vector3(.23f,.60f,.23f),2);var mesh=Bake(r,mats);mesh.name=root.name;string path=Root+"/"+root.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,path);foreach(var p in pieces)Object.DestroyImmediate(p);pieces.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=mats;var col=root.AddComponent<CapsuleCollider>();col.center=new Vector3(0,height/2,0);col.radius=.30f;col.height=height;var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/"+root.name+".prefab");int tris=mesh.triangles.Length/3;total+=tris;if(mesh.bounds.size.y<2.2f||mesh.bounds.size.y>3.1f||tris>5000)throw new Exception("Tree dimensions failed "+mesh.bounds.size);Debug.Log("SCREENING_TREE_PASS "+root.name+" size="+mesh.bounds.size+" triangles="+tris);Object.DestroyImmediate(root);
 }
 Object.DestroyImmediate(clump);var row=new GameObject("ScreeningHedge_20m");for(int i=0;i<27;i++){string name="ScreeningTree_"+(char)('A'+i%3);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/"+name+".prefab"));g.transform.SetParent(row.transform,false);g.transform.localPosition=new Vector3(0,0,(i-13)*.74f);g.transform.localRotation=Quaternion.Euler(0,(i*137)%360,0);}var rowPrefab=PrefabUtility.SaveAsPrefabAsset(row,Root+"/ScreeningHedge_20m.prefab");Object.DestroyImmediate(row);
 Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);PrefabUtility.InstantiatePrefab(rowPrefab);for(int i=0;i<3;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/ScreeningTree_"+(char)('A'+i)+".prefab"));g.transform.position=new Vector3(3.5f,0,-2+i*2);}var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.12f,0);floor.transform.localScale=new Vector3(45,.24f,45);floor.GetComponent<Renderer>().sharedMaterial=Mat("PreviewGround",new Color(.44f,.46f,.40f));var camera=Camera.main;camera.transform.position=new Vector3(16,10,-19);camera.transform.LookAt(new Vector3(0,1,0));camera.fieldOfView=47;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.40f,.48f,.53f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=1.4f;sun.transform.rotation=Quaternion.Euler(40,-35,0);RenderSettings.fog=false;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.6f,.64f,.68f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_ScreeningTrees.unity");AssetDatabase.SaveAssets();Capture(camera);Debug.Log("SCREENING_TREES_BUILD_PASS variants=3 uniqueTriangles="+total+" rowLength=20m sharedMeshes=3 materials=4 runtime=none");} static void Capture(Camera camera){var rt=new RenderTexture(1200,850,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1200,850,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,850),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/ScreeningTrees_Preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}
}
